$ab=$mysqli->query("SELECT o.*,t.nome tecnico_nome,c.nome cliente_nome FROM ordemservicos o LEFT JOIN tecnicos t ON t.id=o.tecnico LEFT JOIN clientes c ON c.id=o.cliente WHERE o.empresa='$empresa' AND o.encerrado='N' ORDER BY o.id DESC");
