function osSit($s){return ['O'=>'Orçamento','I'=>'Instalação concluída','NI'=>'Instalação','M'=>'Manutenção','R'=>'Recuperação','A'=>'Aprovado','C'=>'Cancelada'][$s]??$s;}
function osCl($s){return ['I'=>'ok','A'=>'ok','M'=>'warn','NI'=>'blue','R'=>'violet','C'=>'bad','O'=>'blue'][$s]??'blue';}
